<?php
$done='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $cfg=['db_host'=>trim($_POST['host']),'db_name'=>trim($_POST['name']),'db_user'=>trim($_POST['user']),'db_pass'=>(string)$_POST['dbpass'],'admin_user'=>trim($_POST['admin']),'admin_pass'=>(string)$_POST['adminpass'],'timezone'=>trim($_POST['timezone'])?:'America/Los_Angeles'];
  try{$pdo=new PDO("mysql:host={$cfg['db_host']};dbname={$cfg['db_name']};charset=utf8mb4",$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$sql=file_get_contents(__DIR__.'/database.sql');$pdo->exec($sql);$text="<?php\nreturn ".var_export($cfg,true).";\n";if(file_put_contents(__DIR__.'/config.php',$text)===false)throw new Exception('Không ghi được config.php. Hãy cấp quyền ghi thư mục rồi thử lại.');$done='Cài đặt thành công. Hãy xóa file install.php sau khi kiểm tra.';}catch(Throwable $e){$error=$e->getMessage();}
}
